# Import necessary modules for Python 2 and 3 compatibility
from __future__ import division, print_function, unicode_literals

# Define a function to safely convert a string to Unicode if it's not already
def safe_unicode(value):
    try:
        return str(value)
    except TypeError:
        # Handle cases where value is not a string or not supported by str()
        return u"Unsupported type"

# Define a function to safely format a list into a comma-separated string
def format_list(items):
    return ", ".join(safe_unicode(item) for item in items)

# Define a function to safely convert a dictionary to a formatted string
def format_dict(data):
    return "\n".join(f"{key}: {safe_unicode(value)}" for key, value in data.items())

# Example usage
if __name__ == "__main__":
    # Test safe_unicode function
    print(safe_unicode(42))  # Output: "42"
    print(safe_unicode("Hello"))  # Output: "Hello"

    # Test format_list function
    fruits = ["apple", "banana", "cherry"]
    print(format_list(fruits))  # Output: "apple, banana, cherry"

    # Test format_dict function
    person_info = {"name": "Alice", "age": 30}
    print(format_dict(person_info))  # Output:
    # name: Alice
    # age: 30
```

In this solution, we import the `division`, `print_function`, and `unicode_literals` from the `__future__` module to ensure compatibility across different versions of Python. We define three utility functions: `safe_unicode`, `format_list`, and `format_dict`. These functions handle the conversion of non-string types to strings and the formatting of lists and dictionaries into human-readable formats. The example usage demonstrates how these functions can be used in a simple script.

```python
import re

class TemplateEngine:
    def __init__(self):
        self._template = None
        self._variables = {}

    @classmethod
    def from_string(cls, template_str):
        return cls().set_template(template_str)

    def set_template(self, template_str):
        self._template = template_str
        return self

    def render(self, **kwargs):
        if not self._template:
            raise ValueError("Template has not been set")

        # Replace variables in the template
        for key, value in kwargs.items():
            self._variables[key] = value

        # Parse the template and replace placeholders with actual values
        rendered = self._parse_template()

        return rendered

    def _parse_template(self):
        # Split the template into blocks and placeholders
        blocks = self._split_blocks()

        # Process each block
        for block in blocks:
            block = self._process_block(block)

            # Add back the processed block to the rendered template
            self._template = self._template.replace(f'{{{{{block}}}}}', block)

        return self._template

    def _split_blocks(self):
        # Use regular expressions to split the template into blocks
        blocks = re.split(r'\{\{|\}\}', self._template)
        return blocks

    def _process_block(self, block):
        # Check for conditional blocks
        if '{{#if {{}}}}' in block:
            condition = block.split('{{#if }}')[1].strip()
            if condition in self._variables:
                return f'{{{{{self._variables[condition]}}}}}'
            else:
                return '{{#else}}{{endif}}'

        # Check for nested blocks
        if '{{#for {{}}}}' in block:
            variable = block.split('{{#for }}')[1].strip()
            if variable in self._variables:
                return f'{{{{{self._variables[variable]}}}}}'
            else:
                return '{{#else}}{{endif}}'

        # Return the unprocessed block
        return block.strip()

# Example usage
engine = TemplateEngine.from_string('Hello, {{name}}! {{#if age > 30}}You are old!{{/if}}')
print(engine.render(name='Alice', age=25))  # Output: Hello, Alice! You are young!
```

In this solution, we define a `TemplateEngine` class that can be used to create and render templates with embedded logic and conditions. The `from_string` method initializes a new instance of the engine with a given template string. The `render` method replaces placeholders in the template with actual values based on the provided keyword arguments.

The `_parse_template` method splits the template into blocks and processes them. It checks for conditional blocks (like `{{#if}}` and `{{#else}}`) and nested blocks (like `{{#for}}` and `{{#endfor}}`). For each block, it processes it according to its type and updates the template accordingly.

This implementation provides a simple yet powerful way to create dynamic templates in Python.

```python
# Import necessary libraries
import argparse

# Define a base class for commands
class Command:
    def __init__(self):
        self.parser = argparse.ArgumentParser(description=self.description)

    @property
    def description(self):
        raise NotImplementedError("Subclasses must implement description")

    def add_arguments(self):
        raise NotImplementedError("Subclasses must implement add_arguments")

    def execute(self):
        raise NotImplementedError("Subclasses must implement execute")

# Define a simple command that prints a message
class SimpleCommand(Command):
    @property
    def description(self):
        return "Prints a given message"

    def add_arguments(self):
        self.parser.add_argument('message', help='The message to print')

    def execute(self):
        args = self.parser.parse_args()
        print(args.message)

# Define a composite command that combines multiple subcommands
class CompositeCommand(Command):
    def __init__(self, *subcommands):
        super().__init__()
        self.subcommands = subcommands

    @property
    def description(self):
        return "Combines multiple subcommands into a single workflow"

    def add_arguments(self):
        for subcommand in self.subcommands:
            subcommand.add_arguments()

    def execute(self):
        for subcommand in self.subcommands:
            subcommand.execute()

# Example usage
if __name__ == "__main__":
    # Create a composite command with two subcommands
    command = CompositeCommand(
        SimpleCommand(description="Prints a greeting"),
        SimpleCommand(description="Calculates the sum of two numbers")
    )

    # Execute the composite command
    command.execute()
```

In this solution, we define a `Command` class as the base class for all commands. Each command class should have methods to set up its own parser, add arguments, and execute itself.

We then create a `SimpleCommand` that takes a single argument and prints it. A `CompositeCommand` is a higher-level command that can combine other commands. It iterates over a list of subcommands and executes each one sequentially.

Finally, in the example usage, we create a composite command that includes a greeting command and a calculation command. When executed, the composite command will first print the greeting and then calculate the sum of two numbers.

