# Import necessary libraries
from PIL import Image

class ImageProcessor:
    def __init__(self):
        # Initialize the ImageProcessor class with Pillow
        self.image = None

    def open_image(self, filename):
        # Open an image file using Pillow
        try:
            self.image = Image.open(filename)
            print(f"Image opened successfully: {filename}")
        except IOError as e:
            print(f"Error opening image: {e}")

    def save_image(self, filename):
        # Save the current image in the specified format using Pillow
        if self.image:
            try:
                self.image.save(filename, "PNG")  # Example format, change as needed
                print(f"Image saved successfully: {filename}")
            except IOError as e:
                print(f"Error saving image: {e}")
        else:
            print("No image to save.")

    def resize_image(self, width, height):
        # Resize the image using Pillow
        if self.image:
            try:
                resized_image = self.image.resize((width, height))
                self.image = resized_image
                print(f"Image resized to {width}x{height}")
            except Exception as e:
                print(f"Error resizing image: {e}")
        else:
            print("No image to resize.")

    def crop_image(self, left, upper, right, lower):
        # Crop the image using Pillow
        if self.image:
            try:
                cropped_image = self.image.crop((left, upper, right, lower))
                self.image = cropped_image
                print(f"Image cropped to ({left}, {upper})-{(right, lower)}")
            except Exception as e:
                print(f"Error cropping image: {e}")
        else:
            print("No image to crop.")
```

This Python code defines a class `ImageProcessor` that encapsulates functionality for opening, manipulating, and saving images using the Pillow library. The class provides methods to open an image from a file, save it to a new file in a specific format, resize the image, and crop the image. Each method includes error handling to manage cases where the image cannot be opened or saved correctly.

