```python
import ast
import re

class CyclomaticComplexityChecker(ast.NodeVisitor):
    def __init__(self, max_complexity=10):
        self.max_complexity = max_complexity
        self.complexity_count = 0

    def visit_Compare(self, node):
        if isinstance(node.op, (ast.Eq, ast.NotEq)):
            self.complexity_count += 1
        elif isinstance(node.op, ast.Gt) or isinstance(node.op, ast.Lt) or isinstance(node.op, ast.GtE) or isinstance(node.op, ast.LtE):
            self.complexity_count += 2
        super().visit_Compare(node)

    def visit_If(self, node):
        self.complexity_count += 1
        super().visit_If(node)

    def visit_For(self, node):
        self.complexity_count += 1
        super().visit_For(node)

    def visit_Break(self, node):
        self.complexity_count += 1
        super().visit_Break(node)

    def visit_Continue(self, node):
        self.complexity_count += 1
        super().visit_Continue(node)

    def visit_Return(self, node):
        self.complexity_count += 1
        super().visit_Return(node)

    def visit_FunctionDef(self, node):
        self.complexity_count += 1
        super().visit_FunctionDef(node)

    def visit_Call(self, node):
        if isinstance(node.func, ast.Name):
            func_name = node.func.id
            # Check for common functions with high cyclomatic complexity
            if func_name == "os" and len(node.args) > 3:
                self.complexity_count += 5
            elif func_name == "sys" and len(node.args) > 4:
                self.complexity_count += 5
            # Add more conditions as needed based on your specific requirements
        super().visit_Call(node)

def check_cyclomatic_complexity(file_path, max_complexity=10):
    tree = ast.parse(open(file_path).read())
    checker = CyclomaticComplexityChecker(max_complexity)
    checker.visit(tree)
    if checker.complexity_count > max_complexity:
        print(f"Cyclomatic complexity exceeds {max_complexity}.")
    else:
        print("Cyclomatic complexity is within acceptable limits.")

# Example usage
check_cyclomatic_complexity('example.py', 12)
```

This code snippet defines a `CyclomaticComplexityChecker` class that extends `ast.NodeVisitor`. It counts the number of comparisons, loops, breaks, continues, returns, function definitions, and calls in a given Python file. For each comparison or loop, it adds two to the complexity count. The function `check_cyclomatic_complexity` takes a file path and an optional maximum complexity threshold, parses the file using `ast.parse`, and then uses the visitor to calculate the cyclomatic complexity. If the calculated complexity exceeds the specified threshold, it prints an error message; otherwise, it prints a success message. This plugin can be used with Flake8 to enforce a maximum cyclomatic complexity limit in Python code.

