```python
import ast

def check_security_vulnerabilities(code):
    tree = ast.parse(code)

    # Define a list of known security vulnerabilities and best practices violations
    vulnerabilities = [
        ("SQL Injection", "sql_injection"),
        ("Cross-Site Scripting (XSS)", "xss"),
        ("Insecure Direct Object Reference (IDOR)", "idor"),
        ("Use of Deprecated Functions", "deprecated_functions"),
        ("Hardcoded Credentials", "hardcoded_credentials")
    ]

    # Check each node in the AST
    def check_node(node):
        if isinstance(node, ast.Call) and hasattr(node.func, 'id') and node.func.id in ['open', 'exec']:
            return "Possible SQL Injection or Cross-Site Scripting"

        elif isinstance(node, ast.Call) and hasattr(node.func, 'id') and node.func.id == 'eval':
            return "Possible Code Execution"

        elif isinstance(node, ast.For) or isinstance(node, ast.While):
            if isinstance(node.target, ast.Name) and node.target.id in ['username', 'password']:
                return "Possible Hardcoded Credentials"

            for child in ast.walk(node):
                if isinstance(child, ast.Assign) and len(child.targets) == 1:
                    target = child.targets[0]
                    if isinstance(target, ast.Name) and target.id in ['user_id', 'item_id']:
                        return "Possible Insecure Direct Object Reference"

                elif isinstance(child, ast.If):
                    for stmt in child.body:
                        result = check_node(stmt)
                        if result:
                            return result

    for node in ast.walk(tree):
        result = check_node(node)
        if result:
            print(f"Security Vulnerability: {result}")

# Example usage
