import msgpack

class MessagePackSerializer:
    def serialize(self, data):
        # Convert the Python object into a dictionary (MessagePack does not directly support Python objects)
        message_dict = {
            'type': type(data).__name__,
            'value': data
        }
        # Serialize the dictionary into MessagePack bytes
        return msgpack.dumps(message_dict)

# Example usage:
serializer = MessagePackSerializer()
data_to_serialize = {'name': 'Alice', 'age': 30, 'city': 'Wonderland'}
serialized_data = serializer.serialize(data_to_serialize)
print(serialized_data)
```

In this solution, we define a class `MessagePackSerializer` with a method `serialize` that takes a Python object as input. The method first converts the object into a dictionary where the key is the name of the object's type and the value is the actual object itself. This step is necessary because MessagePack does not natively support Python objects directly.

Next, the dictionary is serialized into MessagePack format using the `msgpack.dumps()` function. This function converts the dictionary into a byte stream that can be sent over a network or stored in a file.

Finally, an example usage of the `MessagePackSerializer` class is provided, where a dictionary representing a person's information is serialized and printed.

import importlib.metadata
from importlib.metadata import DistributionMetadata
import os

def get_package_metadata(package_name):
    try:
        dist_info_path = os.path.join(os.path.dirname(__file__), f"{package_name}-*.dist-info")
        for filename in os.listdir(dist_info_path):
            if filename.endswith(".dist-info"):
                dist_info_file = os.path.join(dist_info_path, filename)
                with open(dist_info_file, 'r') as file:
                    content = file.read()
                    metadata = DistributionMetadata.parse(content)
                    return {
                        "name": metadata.name,
                        "version": metadata.version,
                        "author": metadata.author,
                        "author_email": metadata.author_email
                    }
    except FileNotFoundError:
        pass
    return None

package_name = "my_package"
metadata = get_package_metadata(package_name)
if metadata:
    print(f"Name: {metadata['name']}")
    print(f"Version: {metadata['version']}")
    print(f"Author: {metadata['author']}")
else:
    print("Package metadata not found.")

