import http.client
from urllib.parse import urlencode

class CustomHTTPClient:
    def __init__(self):
        self.host = None
        self.port = None
        self.request_method = None
        self.headers = {}
        self.body = None
        self.response_handler = None

    def set_host(self, host):
        self.host = host

    def set_port(self, port):
        self.port = port

    def set_request_method(self, method):
        self.request_method = method.upper()

    def set_headers(self, headers):
        self.headers = headers

    def set_body(self, body):
        self.body = body

    def set_response_handler(self, handler):
        self.response_handler = handler

    def send_request(self):
        if not self.host or not self.port or not self.request_method or not self.headers:
            raise ValueError("All required fields must be set before sending a request.")

        conn = http.client.HTTPConnection(self.host, self.port)
        conn.request(self.request_method, '/', self.body, self.headers)

        try:
            response = conn.getresponse()
            return response.read(), response.status, response.reason
        except Exception as e:
            return None, 500, str(e)
        finally:
            conn.close()

def custom_http_client_example():
    client = CustomHTTPClient()
    client.set_host('example.com')
    client.set_port(80)
    client.set_request_method('GET')
    client.set_headers({'User-Agent': 'CustomPythonHTTPClient'})
    client.send_request()

    status_code, response_body, reason = custom_http_client_example()
    print(f"Status Code: {status_code}")
    print(f"Response Body: {response_body.decode('utf-8')}")
    print(f"Reason: {reason}")

custom_http_client_example()
```

This Python code defines a `CustomHTTPClient` class that encapsulates the functionality of an HTTP client, allowing for setting various parameters such as host, port, request method, headers, and body. The `send_request` method sends the configured HTTP request to the server and returns the response. The `custom_http_client_example` function demonstrates how to use the `CustomHTTPClient` class to send a GET request to an example.com server and print the response status code, body, and reason.

