import argparse
import requests

def execute_query(query):
    url = "https://<your-databricks-instance>/api/2.0/sql"
    headers = {
        "Authorization": f"Bearer {os.getenv('DATABRICKS_TOKEN')}",
        "Content-Type": "application/json"
    }
    response = requests.post(url, headers=headers, json={"sql": query})
    if response.status_code == 200:
        return response.json()
    else:
        return None

def create_database(name):
    url = f"https://<your-databricks-instance>/api/2.0/databases/{name}"
    headers = {
        "Authorization": f"Bearer {os.getenv('DATABRICKS_TOKEN')}",
        "Content-Type": "application/json"
    }
    response = requests.put(url, headers=headers)
    if response.status_code == 200:
        return True
    else:
        return False

def drop_database(name):
    url = f"https://<your-databricks-instance>/api/2.0/databases/{name}"
    headers = {
        "Authorization": f"Bearer {os.getenv('DATABRICKS_TOKEN')}",
        "Content-Type": "application/json"
    }
    response = requests.delete(url, headers=headers)
    if response.status_code == 200:
        return True
    else:
        return False

def list_databases():
    url = "https://<your-databricks-instance>/api/2.0/databases"
    headers = {
        "Authorization": f"Bearer {os.getenv('DATABRICKS_TOKEN')}",
        "Content-Type": "application/json"
    }
    response = requests.get(url, headers=headers)
    if response.status_code == 200:
        return response.json()
    else:
        return None

def main():
    parser = argparse.ArgumentParser(description="Command line interface for Databricks")
    subparsers = parser.add_subparsers(dest="command")

    # Query execution
    query_parser = subparsers.add_parser("query", help="Execute an SQL query")
    query_parser.add_argument("query", type=str, help="The SQL query to execute")

    # Create database
    create_parser = subparsers.add_parser("create-db", help="Create a new database")
    create_parser.add_argument("name", type=str, help="The name of the database to create")

    # Drop database
    drop_parser = subparsers.add_parser("drop-db", help="Drop an existing database")
    drop_parser.add_argument("name", type=str, help="The name of the database to drop")

    # List databases
    list_parser = subparsers.add_parser("list-dbs", help="List all databases in the workspace")

    args = parser.parse_args()

    if args.command == "query":
        result = execute_query(args.query)
        if result:
            print(result)
        else:
            print("Failed to execute query")
    elif args.command == "create-db":
        success = create_database(args.name)
        if success:
            print(f"Database '{args.name}' created successfully")
        else:
            print("Failed to create database")
    elif args.command == "drop-db":
        success = drop_database(args.name)
        if success:
            print(f"Database '{args.name}' dropped successfully")
        else:
            print("Failed to drop database")
    elif args.command == "list-dbs":
        databases = list_databases()
        if databases:
            for db in databases:
                print(db["name"])
        else:
            print("No databases found")

if __name__ == "__main__":
    import os
    os.environ["DATABRICKS_TOKEN"] = "<your-databricks-token>"
    main()
```

This Python script provides a command line interface for interacting with Databricks using the Databricks API. It includes functions to execute SQL queries, create and manage databases, and list all databases in the workspace. The script uses `argparse` to parse command-line arguments and makes HTTP requests to the Databricks REST API based on the user's commands. The `execute_query`, `create_database`, `drop_database`, and `list_databases` functions handle different operations related to database management. The script also sets up environment variables for the Databricks token before running the main function.

