def test_file_existence(file_path):
    if os.path.exists(file_path):
        print(f"File {file_path} exists.")
    else:
        print(f"File {file_path} does not exist.")

# Function to test file content
def test_file_content(file_path, expected_content):
    with open(file_path, 'r') as file:
        actual_content = file.read()
        if actual_content == expected_content:
            print(f"File {file_path} contains the expected content.")
        else:
            print(f"File {file_path} does not contain the expected content.")

# Function to test directory existence
