def grpc_status_to_string(status):
    # Check each status code and return the corresponding string
    if status == status_pb2.OK:
        return "OK"
    elif status == status_pb2.CANCELLED:
        return "CANCELLED"
    elif status == status_pb2.UNKNOWN:
        return "UNKNOWN"
    elif status == status_pb2.INVALID_ARGUMENT:
        return "INVALID_ARGUMENT"
    elif status == status_pb2.DEADLINE_EXCEEDED:
        return "DEADLINE_EXCEEDED"
    elif status == status_pb2.NOT_FOUND:
        return "NOT_FOUND"
    elif status == status_pb2.ALREADY_EXISTS:
        return "ALREADY_EXISTS"
    elif status == status_pb2.PERMISSION_DENIED:
        return "PERMISSION_DENIED"
    elif status == status_pb2.FAILED_PRECONDITION:
        return "FAILED_PRECONDITION"
    elif status == status_pb2.OUT_OF_RANGE:
        return "OUT_OF_RANGE"
    elif status == status_pb2.UNIMPLEMENTED:
        return "UNIMPLEMENTED"
    elif status == status_pb2.INTERNAL:
        return "INTERNAL"
    elif status == status_pb2.DATA_LOSS:
        return "DATA_LOSS"
    else:
        return "UNKNOWN"

# Example usage of the function
