import requests

# Function to send a GET request
def get_request(url):
    try:
        response = requests.get(url)
        response.raise_for_status()  # Raises an HTTPError for bad responses
        print(f"GET request successful: {response.status_code}")
        return response.json()
    except requests.exceptions.RequestException as e:
        print(f"GET request failed: {e}")

# Function to send a POST request
def post_request(url, data):
    try:
        response = requests.post(url, json=data)
        response.raise_for_status()
        print(f"POST request successful: {response.status_code}")
        return response.json()
    except requests.exceptions.RequestException as e:
        print(f"POST request failed: {e}")

# Function to send a PUT request
def put_request(url, data):
    try:
        response = requests.put(url, json=data)
        response.raise_for_status()
        print(f"PUT request successful: {response.status_code}")
        return response.json()
    except requests.exceptions.RequestException as e:
        print(f"PUT request failed: {e}")

# Function to send a DELETE request
def delete_request(url):
    try:
        response = requests.delete(url)
        response.raise_for_status()
        print(f"DELETE request successful: {response.status_code}")
        return response.json()
    except requests.exceptions.RequestException as e:
        print(f"DELETE request failed: {e}")

# Example usage of functions
url = "https://api.example.com/data"
data = {"key": "value"}
get_response(url)
post_response(url, data)
put_response(url, data)
delete_request(url)
```

