import os
from google.oauth2.service_account import Credentials
from googleapiclient.discovery import build

# Define constants for scopes and credentials file path
SCOPES = ['https://www.googleapis.com/auth/spreadsheets.readwrite']
CREDENTIALS_FILE_PATH = 'path/to/your/service-account-file.json'

def authenticate():
    """Authenticate with the Google Sheets API."""
    creds = None
    if os.path.exists(CREDENTIALS_FILE_PATH):
        creds = Credentials.from_service_account_file(_credentials_FILE_PATH)
    return creds

def get_sheets_service(creds):
    """Build and return the Google Sheets service object."""
    service = build('sheets', 'v4', credentials=creds)
    return service

def create_sheet(service, spreadsheet_id, title):
    """Create a new sheet in the specified spreadsheet."""
    body = {
        "properties": {
            "title": title,
            "sheetType": "GRID"
        }
    }
    result = service.spreadsheets().sheets().create(body=body, spreadsheetId=spreadsheet_id).execute()
    print(f"Sheet created: {result['properties']['title']}")

def list_sheets(service, spreadsheet_id):
    """List all sheets in the specified spreadsheet."""
    results = service.spreadsheets().sheets().list(spreadsheetId=spreadsheet_id).execute()
    sheets = results.get('sheets', [])
    for sheet in sheets:
        print(f"Sheet ID: {sheet['properties']['sheetId']}, Title: {sheet['properties']['title']}")

def rename_sheet(service, spreadsheet_id, old_title, new_title):
    """Rename an existing sheet in the specified spreadsheet."""
    request_body = {
        "requests": [
            {
                "updateSheetProperties": {
                    "properties": {
                        "title": new_title
                    },
                    "fields": "title"
                }
            }
        ]
    }
    result = service.spreadsheets().batchUpdate(spreadsheetId=spreadsheet_id, body=request_body).execute()
    print(f"Sheet renamed from '{old_title}' to '{new_title}'")

def delete_sheet(service, spreadsheet_id, sheet_id):
    """Delete an existing sheet from the specified spreadsheet."""
    request_body = {
        "requests": [
            {
                "deleteSheet": {
                    "sheetId": sheet_id
                }
            }
        ]
    }
    result = service.spreadsheets().batchUpdate(spreadsheet_id=spreadsheet_id, body=request_body).execute()
    print(f"Sheet deleted with ID: {sheet_id}")

def format_cell(service, spreadsheet_id, sheet_id, row, col, value, formatting=None):
    """Format a cell in the specified spreadsheet."""
    body = {
        "requests": [
            {
                "repeatCell": {
                    "range": {
                        "sheetId": sheet_id,
                        "startRowIndex": row - 1,
                        "endRowIndex": row - 1,
                        "startColumnIndex": col - 1,
                        "endColumnIndex": col - 1
                    },
                    "cell": {
                        "value": value,
                        "format": formatting
                    },
                    "fields": "userEnteredValue.format"
                }
            }
        ]
    }
    result = service.spreadsheets().batchUpdate(spreadsheet_id=spreadsheet_id, body=body).execute()
    print(f"Cell formatted in row {row}, column {col}: {value}")

def main():
    # Authenticate and get the service object
    creds = authenticate()
    service = get_sheets_service(creds)

    # Create a new sheet
    create_sheet(service, 'your-spreadsheet-id', 'New Sheet')

    # List all sheets
    list_sheets(service, 'your-spreadsheet-id')

    # Rename an existing sheet
    rename_sheet(service, 'your-spreadsheet-id', 'Old Sheet', 'Renamed Sheet')

    # Delete an existing sheet
    delete_sheet(service, 'your-spreadsheet-id', 'SheetToDelete')

    # Format a cell
    format_cell(service, 'your-spreadsheet-id', 'SheetToFormat', 1, 1, 'Hello World!', {'numberFormat': {'type': 'NUMBER'}})

if __name__ == "__main__":
    main()
```

This Python script demonstrates how to interact with the Google Sheets API using OAuth2 authentication and performs various operations such as creating, listing, renaming, deleting, and formatting sheets within a Google Sheets document. The script includes functions for each operation and a `main` function to execute these operations sequentially.

