# Import necessary libraries
from google.cloud import secretmanager_v1

def create_secret(project_id, secret_id):
    # Create a client for Secret Manager
    client = secretmanager_v1.SecretManagerClient()

    # Define the secret version payload
    payload = {
        "data": b"Your secret data here",
        "labels": {"environment": "production"}
    }

    # Create a secret version
    response = client.create_secret_version(
        parent=f"projects/{project_id}/secrets/{secret_id}",
        secret_version={
            "payload": payload,
            "state": "ENABLED"
        }
    )

    print(f"Created secret version: {response.name}")

def get_secret(project_id, secret_id):
    # Create a client for Secret Manager
    client = secretmanager_v1.SecretManagerClient()

    # Get the secret version
    response = client.get_secret_version(
        name=f"projects/{project_id}/secrets/{secret_id}/versions/latest"
    )

    print(f"Secret contents: {response.payload.data.decode('utf-8')}")

def update_secret(project_id, secret_id):
    # Create a client for Secret Manager
    client = secretmanager_v1.SecretManagerClient()

    # Update the secret version
    response = client.update_secret_version(
        name=f"projects/{project_id}/secrets/{secret_id}/versions/latest",
        secret_version={
            "payload": {
                "data": b"Updated secret data here",
                "labels": {"environment": "development"}
            },
            "state": "DISABLED"
        }
    )

    print(f"Updated secret version: {response.name}")

def delete_secret(project_id, secret_id):
    # Create a client for Secret Manager
    client = secretmanager_v1.SecretManagerClient()

    # Delete the secret version
    response = client.delete_secret_version(
        name=f"projects/{project_id}/secrets/{secret_id}/versions/latest"
    )

    print(f"Deleted secret version: {response.name}")

def list_secrets(project_id):
    # Create a client for Secret Manager
    client = secretmanager_v1.SecretManagerClient()

    # List all secrets in the project
    response = client.list_secrets(
        parent=f"projects/{project_id}"
    )

    for secret in response.secrets:
        print(f"Secret ID: {secret.name}")

def fetch_secret_versions(project_id, secret_id):
    # Create a client for Secret Manager
    client = secretmanager_v1.SecretManagerClient()

    # Fetch all versions of the secret
    response = client.list_secret_versions(
        name=f"projects/{project_id}/secrets/{secret_id}"
    )

    for version in response.secret_versions:
        print(f"Version: {version.name}, State: {version.state}")
```

