import os
import subprocess

class LanguagePreCommit:
    def __init__(self, config_file):
        self.config = self.load_config(config_file)
        self.hooks = {}

    def load_config(self, config_file):
        with open(config_file, 'r') as file:
            return eval(file.read())

    def register_hook(self, language, command):
        if language not in self.hooks:
            self.hooks[language] = []
        self.hooks[language].append(command)

    def run_hooks(self, files):
        for language, commands in self.hooks.items():
            for command in commands:
                # Check if the command is executable
                if os.access(command, os.X_OK):
                    # Execute the command on each file
                    subprocess.run([command] + files, check=True)
                else:
                    print(f"Warning: Command '{command}' is not executable.")
```

This Python code defines a `LanguagePreCommit` class that manages and maintains multi-language pre-commit hooks. The class reads a centralized configuration file to define hooks and their associated languages. It allows registering new hooks and executing them during the commit process. The class supports multiple version control systems by checking if the commands used are executable before running them.

import json
from config import Config

def load_config(file_path):
    try:
        with open(file_path, 'r') as file:
            return json.load(file)
    except FileNotFoundError:
        print(f"Error: The file {file_path} was not found.")
        return None

def validate_config(config):
    if not isinstance(config, Config):
        raise ValueError("The loaded configuration must be an instance of Config.")

    # Additional validation logic if needed
    if config.port < 1000 or config.port > 65535:
        raise ValueError("Port number must be between 1000 and 65535.")

if __name__ == "__main__":
    config_file = 'config.json'
    config_data = load_config(config_file)

    if config_data:
        config = Config(**config_data)
        validate_config(config)
        print(f"Configuration is valid: {config}")
    else:
        exit(1)

